when isMainModule:
  let text = "Word1\u2003Word2" # U+2003 is Em Space

  var words = 0
  var inWord = false
  for r in text.runes:
    if r.isWhiteSpace():
      inWord = false
    else:
      if not inWord:
        words += 1
        inWord = true

  echo "Word count: ", words
